const fits = (
		lParts: string[],
		hOptions: TNiceOptions
		): boolean => {

	const {pre, maxWidth} = hOptions
	const total = accum(lParts, 0, (x, acc, i) => {
		return acc + ((i===0) ? x.length : x.length+1)
	})
	return (total + pre.length + 2 <= maxWidth)
}

